// 平坦化した全例文リスト（タイピング練習・読解等で直接利用可能）
const textbookSentences = textbookLessonsData.flatMap(lesson => 
  (lesson.sentences || []).map(s => ({
    ...s,
    lessonNumber: lesson.lesson,
    lessonTitle: lesson.title
  }))
);

if (typeof window !== 'undefined') {
  window.textbookLessonsData = textbookLessonsData;
  window.textbookSentences = textbookSentences;
}


