// === js/services/srs.js ===
// 間隔反復学習（Spaced Repetition System / 忘却曲線）エンジン
// SuperMemo SM-2 および FSRS (Free Spaced Repetition Scheduler) の原理に基づく実装

class SrsService {
  // 復習間隔テーブル（日数）: レベル0(未学習)〜レベル8+(完全習得)
  static INTERVALS = [0, 1, 3, 7, 14, 30, 60, 90, 180];

  // 習熟度ラベル定義
  static MASTERY_LEVELS = [
    { level: 0, label: '未学習', color: 'slate', badge: 'bg-slate-100 text-slate-600 border-slate-200' },
    { level: 1, label: '初見 (Lv.1)', color: 'amber', badge: 'bg-amber-50 text-amber-700 border-amber-200' },
    { level: 2, label: '基礎定着 (Lv.2)', color: 'amber', badge: 'bg-amber-100 text-amber-800 border-amber-300' },
    { level: 3, label: '定着中 (Lv.3)', color: 'sky', badge: 'bg-sky-50 text-sky-700 border-sky-200' },
    { level: 4, label: '記憶安定 (Lv.4)', color: 'sky', badge: 'bg-sky-100 text-sky-800 border-sky-300' },
    { level: 5, label: '長期記憶 (Lv.5)', color: 'emerald', badge: 'bg-emerald-50 text-emerald-700 border-emerald-200' },
    { level: 6, label: '習得済 (Lv.6)', color: 'emerald', badge: 'bg-emerald-100 text-emerald-800 border-emerald-300' },
    { level: 7, label: 'マスター (Lv.7)', color: 'purple', badge: 'bg-purple-100 text-purple-800 border-purple-300' }
  ];

  /**
   * 単語のSRS進捗データを初期化または正規化
   */
  static normalizeProgress(prog = {}, wordId = '') {
    return {
      wordId: prog.wordId || wordId,
      srsLevel: typeof prog.srsLevel === 'number' ? prog.srsLevel : 0,
      intervalDays: typeof prog.intervalDays === 'number' ? prog.intervalDays : 0,
      nextReviewDate: prog.nextReviewDate || null, // 'YYYY-MM-DD'
      lastLearnedAt: prog.lastLearnedAt || null,   // ISO string
      studyCount: prog.studyCount || 0,
      correctCount: prog.correctCount || 0,
      wrongCount: prog.wrongCount || 0,
      accuracy: typeof prog.accuracy === 'number' ? prog.accuracy : 0,
      updatedAt: prog.updatedAt || new Date().toISOString()
    };
  }

  /**
   * 今日の日付文字列 (YYYY-MM-DD)
   */
  static getTodayString() {
    const d = new Date();
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  /**
   * 日付に日数を加算した YYYY-MM-DD 文字列を取得
   */
  static addDays(dateStr, days) {
    const base = dateStr ? new Date(dateStr) : new Date();
    base.setDate(base.getDate() + days);
    const year = base.getFullYear();
    const month = String(base.getMonth() + 1).padStart(2, '0');
    const day = String(base.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  /**
   * 忘却リスク（0%〜100%）および記憶保持率（0%〜100%）を計算
   * エビングハウスの忘却曲線近似式: R = e^(-t / S)
   */
  static calculateRetention(prog) {
    if (!prog || !prog.lastLearnedAt || prog.srsLevel === 0) {
      return { retention: 0, forgettingRisk: 100, isDue: true, hasMistake: false };
    }

    const last = new Date(prog.lastLearnedAt).getTime();
    const now = Date.now();
    const diffDays = Math.max(0, (now - last) / (1000 * 60 * 60 * 24));
    const interval = Math.max(1, prog.intervalDays || 1);

    // 一度でも間違えたことのある単語は忘却曲線に組み込み、減衰速度を速めて頻出復習化
    const hasMistake = Boolean((prog.wrongCount && prog.wrongCount > 0) || prog.hasEverBeenMistaken);
    const decayMultiplier = hasMistake ? 0.60 : 1.15;

    // 安定度 S に基づく保持率 R（一度間違えた単語は早く忘却リスクが上昇する）
    const r = Math.exp(-diffDays / (interval * decayMultiplier));
    const retention = Math.max(0, Math.min(100, Math.round(r * 100)));
    const forgettingRisk = Math.max(0, Math.min(100, 100 - retention));

    const today = this.getTodayString();
    // 一度間違えた単語は1日経過しているか高リスク（40%以上）の場合、優先的に復習期日として判定
    const isDue = Boolean(
      (prog.nextReviewDate && prog.nextReviewDate <= today) ||
      (hasMistake && diffDays >= 1 && prog.srsLevel < 6)
    );

    return { retention, forgettingRisk, isDue, diffDays: Math.round(diffDays), hasMistake };
  }

  /**
   * 解答結果に基づいてSRS進捗を更新
   * @param {Object} currentProg 既存の進捗データ
   * @param {boolean} isCorrect 正解したかどうか
   * @param {string} difficulty 'easy' | 'good' | 'hard' (デフォルト: good)
   */
  static processAnswer(currentProg, isCorrect, difficulty = 'good') {
    const prog = this.normalizeProgress(currentProg);
    const today = this.getTodayString();
    const nowIso = new Date().toISOString();

    prog.studyCount += 1;
    prog.lastLearnedAt = nowIso;
    prog.updatedAt = nowIso;

    if (isCorrect) {
      prog.correctCount += 1;
      prog.consecutiveCorrect = (prog.consecutiveCorrect || 0) + 1;

      // 初回学習
      if (prog.srsLevel === 0) {
        prog.srsLevel = 1;
        prog.intervalDays = 1;
      } else {
        // レベル上昇
        prog.srsLevel = Math.min(8, prog.srsLevel + 1);

        // 間隔計算
        let multiplier = 2.1;
        if (difficulty === 'easy') multiplier = 2.6;
        if (difficulty === 'hard') multiplier = 1.4;

        // 一度間違えた単語は、完全に定着するまで短いインターバルで頻繁に出題
        if (prog.hasEverBeenMistaken || prog.wrongCount > 0) {
          const mistakeIntervals = [0, 1, 2, 3, 5, 8, 14, 21, 30];
          prog.intervalDays = mistakeIntervals[Math.min(prog.srsLevel, mistakeIntervals.length - 1)];
        } else if (prog.srsLevel < this.INTERVALS.length) {
          prog.intervalDays = this.INTERVALS[prog.srsLevel];
        } else {
          prog.intervalDays = Math.round((prog.intervalDays || 60) * multiplier);
        }
      }

      prog.nextReviewDate = this.addDays(today, prog.intervalDays);
    } else {
      // 不正解の場合（一度間違えた単語フラグをONにし、忘却曲線の高頻度復習対象へ）
      prog.wrongCount += 1;
      prog.hasEverBeenMistaken = true;
      prog.consecutiveCorrect = 0;
      // レベル低下
      prog.srsLevel = Math.max(1, Math.floor(prog.srsLevel / 2));
      prog.intervalDays = 1; // 明日または直後に即時再復習
      prog.nextReviewDate = today; // 今日〜明日の復習対象
    }

    const total = prog.correctCount + prog.wrongCount;
    prog.accuracy = total > 0 ? Math.round((prog.correctCount / total) * 100) : 0;

    return prog;
  }

  /**
   * 習熟度メタデータを取得
   */
  static getMasteryMeta(srsLevel = 0) {
    const idx = Math.min(this.MASTERY_LEVELS.length - 1, Math.max(0, srsLevel));
    return this.MASTERY_LEVELS[idx];
  }

  /**
   * 復習予定単語の判定
   */
  static isDueForReview(prog) {
    if (!prog || prog.srsLevel === 0) return false;
    const today = this.getTodayString();
    return Boolean(prog.nextReviewDate && prog.nextReviewDate <= today);
  }

  /**
   * 高忘却リスク単語の判定（忘却リスク >= 60%）
   */
  static isHighRisk(prog) {
    if (!prog || prog.srsLevel === 0) return false;
    const stat = this.calculateRetention(prog);
    return stat.forgettingRisk >= 60;
  }
}


// === js/services/auth.js ===
// ユーザー名・パスワード認証サービス（Web Crypto API暗号化・復旧コード対応）
// メールアドレス・Googleアカウント一切不要の独立した認証システム

class AuthService {
  static SESSION_KEY = 'mongol_app_auth_session_v1';
  static LOCAL_USERS_KEY = 'mongol_app_local_users_v1';

  // --- 暗号化ユーティリティ（Web Crypto API） ---

  /**
   * ランダムなソルトを生成 (hex)
   */
  static generateSalt(bytes = 16) {
    const array = new Uint8Array(bytes);
    window.crypto.getRandomValues(array);
    return Array.from(array).map(b => b.toString(16).padStart(2, '0')).join('');
  }

  /**
   * PBKDF2-SHA256 でパスワードを安全にハッシュ化
   */
  static async hashPassword(password, saltHex) {
    const enc = new TextEncoder();
    const keyMaterial = await window.crypto.subtle.importKey(
      'raw',
      enc.encode(password),
      { name: 'PBKDF2' },
      false,
      ['deriveBits', 'deriveKey']
    );

    // ソルトをUint8Arrayに変換
    const saltBytes = new Uint8Array(saltHex.match(/.{1,2}/g).map(byte => parseInt(byte, 16)));

    const derivedKey = await window.crypto.subtle.deriveKey(
      {
        name: 'PBKDF2',
        salt: saltBytes,
        iterations: 100000,
        hash: 'SHA-256'
      },
      keyMaterial,
      { name: 'AES-GCM', length: 256 },
      true,
      ['encrypt']
    );

    const exported = await window.crypto.subtle.exportKey('raw', derivedKey);
    return Array.from(new Uint8Array(exported)).map(b => b.toString(16).padStart(2, '0')).join('');
  }

  /**
   * 16桁のワンタイム復旧コードを生成 (例: MN-8F2A-99B1-C4E2)
   */
  static generateRecoveryCode() {
    const array = new Uint8Array(6);
    window.crypto.getRandomValues(array);
    const hex = Array.from(array).map(b => b.toString(16).toUpperCase().padStart(2, '0')).join('');
    return `MN-${hex.substring(0, 4)}-${hex.substring(4, 8)}-${hex.substring(8, 12)}`;
  }

  /**
   * 復旧コードのハッシュを計算
   */
  static async hashRecoveryCode(code, saltHex) {
    const cleanCode = code.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
    return this.hashPassword(cleanCode, saltHex);
  }

  // --- ユーザー名正規化 ---

  /**
   * ユーザー名の正規化
   * 1. 全角英数字・互換文字の半角化 (Unicode NFKC)
   * 2. 全角ダッシュ・ハイフン・長音（ー―－‐）および全角アンダースコア（＿）の半角統一
   * 3. 全角スペース（\u3000）および前後の空白除去
   * 4. 小文字化（英字）
   */
  static normalizeUsername(username) {
    if (!username) return '';
    let norm = String(username).normalize('NFKC');
    norm = norm.replace(/[ー―－‐]/g, '-').replace(/[＿]/g, '_');
    norm = norm.trim();
    return norm.toLowerCase();
  }

  // --- ローカルユーザー管理 ---

  static getLocalUsers() {
    try {
      const data = localStorage.getItem(this.LOCAL_USERS_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  static saveLocalUsers(users) {
    localStorage.setItem(this.LOCAL_USERS_KEY, JSON.stringify(users));
  }

  // --- 現在のセッション ---

  static getCurrentUser() {
    try {
      const data = localStorage.getItem(this.SESSION_KEY);
      return data ? JSON.parse(data) : null;
    } catch (e) {
      return null;
    }
  }

  static setSession(user) {
    const sessionData = {
      id: user.id,
      username: this.normalizeUsername(user.username),
      displayName: user.displayName || user.username,
      loggedInAt: new Date().toISOString()
    };
    localStorage.setItem(this.SESSION_KEY, JSON.stringify(sessionData));
    return sessionData;
  }

  static logout() {
    localStorage.removeItem(this.SESSION_KEY);
  }

  // --- アカウント新規登録 ---

  /**
   * ユーザー名とパスワードによる登録（メール不要・Google不要）
   */
  static async register(username, password) {
    const rawUsername = (username || '').trim();
    const cleanUsername = this.normalizeUsername(rawUsername);

    if (!cleanUsername || cleanUsername.length < 2) {
      return { success: false, error: 'ユーザー名は2文字以上で入力してください。', code: 'TOO_SHORT' };
    }

    // 英数字、日本語（漢字・ひらがな・カタカナ）、キリル文字、ハイフン、アンダースコアを許可
    if (!/^[\p{L}\p{N}_-]+$/u.test(cleanUsername)) {
      return {
        success: false,
        error: 'ユーザー名には文字（半角英数・日本語・キリル文字）、ハイフン、アンダースコアが使用できます。記号やスペースは使えません。',
        code: 'INVALID_CHARS'
      };
    }

    if (!password || password.length < 6) {
      return { success: false, error: 'パスワードは6文字以上で入力してください。', code: 'PASSWORD_TOO_SHORT' };
    }

    // 重複チェック（正規化後の文字列で比較）
    const users = this.getLocalUsers();
    const existing = users.find(u => this.normalizeUsername(u.username) === cleanUsername);
    if (existing) {
      const display = existing.displayName || existing.username;
      return {
        success: false,
        error: `ユーザー名「${display}」は既に登録されています。「ログイン」タブからログインしてください。`,
        code: 'USER_EXISTS',
        existingUsername: display
      };
    }

    // パスワードと復旧コードのハッシュ化
    const salt = this.generateSalt();
    const passwordHash = await this.hashPassword(password, salt);
    const recoveryCode = this.generateRecoveryCode();
    const recoverySalt = this.generateSalt();
    const recoveryCodeHash = await this.hashRecoveryCode(recoveryCode, recoverySalt);

    const newUser = {
      id: `usr_${Date.now()}_${this.generateSalt(4)}`,
      username: cleanUsername,
      displayName: rawUsername,
      salt: salt,
      passwordHash: passwordHash,
      recoverySalt: recoverySalt,
      recoveryCodeHash: recoveryCodeHash,
      recoveryUsed: false,
      createdAt: new Date().toISOString(),
      lastLoginAt: new Date().toISOString()
    };

    users.push(newUser);
    this.saveLocalUsers(users);

    // 自動ログイン
    const session = this.setSession(newUser);
    this.syncUserToServer(newUser);

    return {
      success: true,
      user: session,
      recoveryCode: recoveryCode
    };
  }

  // --- ログイン ---

  /**
   * ユーザー名とパスワードによるログイン
   */
  static async login(username, password) {
    const rawUsername = (username || '').trim();
    const cleanUsername = this.normalizeUsername(rawUsername);

    if (!cleanUsername || !password) {
      return { success: false, error: 'ユーザー名とパスワードを入力してください。', code: 'MISSING_FIELDS' };
    }

    let users = this.getLocalUsers();
    let user = users.find(u => this.normalizeUsername(u.username) === cleanUsername);

    // 端末内に該当アカウントが存在しない場合、まずクラウド（Supabase）からアカウントを自動検索
    if (!user) {
      try {
        if (typeof SyncService !== 'undefined' && SyncService.fetchAccountFromCloud) {
          const cloudAccounts = await SyncService.fetchAccountFromCloud(cleanUsername);
          if (cloudAccounts && cloudAccounts.length > 0) {
            this.mergeServerUsers(cloudAccounts);
            users = this.getLocalUsers();
            user = users.find(u => this.normalizeUsername(u.username) === cleanUsername);
          }
        }
      } catch (err) {
        console.warn('[AuthService] fetchAccountFromCloud error:', err);
      }

      // Supabaseにない場合、LANサーバー（/api/accounts）からの取得を試みる
      if (!user) {
        try {
          const serverUsers = await this.fetchServerAccounts();
          if (serverUsers && serverUsers.length > 0) {
            this.mergeServerUsers(serverUsers);
            users = this.getLocalUsers();
            user = users.find(u => this.normalizeUsername(u.username) === cleanUsername);
          }
        } catch (_) {}
      }

      if (!user) {
        try {
          const syncData = await this.fetchServerUserData(cleanUsername);
          if (syncData && syncData.account) {
            this.mergeServerUsers([syncData.account]);
            users = this.getLocalUsers();
            user = users.find(u => this.normalizeUsername(u.username) === cleanUsername);
          }
        } catch (_) {}
      }
    }

    // 端末内に保存されているアカウントが1件もない場合
    if (!user) {
      if (!users || users.length === 0) {
        return {
          success: false,
          error: `この端末・ブラウザには登録されたアカウントがありません。PC画面の「📱 タブレット連携」QRコードを読み取ってワンタップログインするか、「新規登録」タブから「${rawUsername}」のアカウントを作成してください。`,
          code: 'NO_USERS_ON_DEVICE',
          inputUsername: rawUsername
        };
      }
      const knownUsers = users.map(u => u.displayName || u.username);
      return {
        success: false,
        error: `ユーザー名「${rawUsername}」のアカウントが見つかりません。PC側の「📱 タブレット連携」QRコードを読み取ってログインするか、スペルをお確かめください。`,
        code: 'USER_NOT_FOUND',
        inputUsername: rawUsername,
        registeredUsers: knownUsers
      };
    }

    const testHash = await this.hashPassword(password, user.salt);
    if (testHash !== user.passwordHash) {
      return {
        success: false,
        error: 'ユーザー名は確認できましたが、パスワードが一致しません。入力内容をお確かめいただくか、復旧コードをお試しください。',
        code: 'PASSWORD_MISMATCH',
        matchedUsername: user.displayName || user.username
      };
    }

    user.lastLoginAt = new Date().toISOString();
    this.saveLocalUsers(users);

    const session = this.setSession(user);
    
    // サーバー上の最新学習データをローカルへ反映
    try {
      const serverSync = await this.fetchServerUserData(cleanUsername);
      if (serverSync && serverSync.storage) {
        this.restoreStorageSnapshot(serverSync.storage);
      } else {
        // サーバー側にデータがまだなければ現在のローカルデータをサーバーへ同期
        this.syncAllToServer(cleanUsername);
      }
    } catch (_) {}

    return { success: true, user: session };
  }

  // --- パスワード復旧（ワンタイム復旧コード） ---

  /**
   * 復旧コードによるパスワード再設定
   */
  static async resetPasswordWithRecoveryCode(username, recoveryCode, newPassword) {
    const rawUsername = (username || '').trim();
    const cleanUsername = this.normalizeUsername(rawUsername);

    if (!cleanUsername || !recoveryCode || !newPassword) {
      return { success: false, error: 'すべての項目を入力してください。', code: 'MISSING_FIELDS' };
    }
    if (newPassword.length < 6) {
      return { success: false, error: '新しいパスワードは6文字以上で入力してください。', code: 'PASSWORD_TOO_SHORT' };
    }

    const users = this.getLocalUsers();
    const user = users.find(u => this.normalizeUsername(u.username) === cleanUsername);

    if (!user) {
      return { success: false, error: `ユーザー名「${rawUsername}」が見つかりません。`, code: 'USER_NOT_FOUND' };
    }

    if (user.recoveryUsed) {
      return { success: false, error: 'この復旧コードは既に使用済みです。', code: 'CODE_ALREADY_USED' };
    }

    const testRecoveryHash = await this.hashRecoveryCode(recoveryCode, user.recoverySalt);
    if (testRecoveryHash !== user.recoveryCodeHash) {
      return {
        success: false,
        error: '復旧コードが正しくありません。ハイフンを含めて正確に入力してください（例: MN-XXXX-XXXX-XXXX）。',
        code: 'INVALID_CODE'
      };
    }

    // 新しいパスワードをハッシュ化
    const newSalt = this.generateSalt();
    user.salt = newSalt;
    user.passwordHash = await this.hashPassword(newPassword, newSalt);

    // 新しい復旧コードを発行
    const newRecoveryCode = this.generateRecoveryCode();
    const newRecoverySalt = this.generateSalt();
    user.recoverySalt = newRecoverySalt;
    user.recoveryCodeHash = await this.hashRecoveryCode(newRecoveryCode, newRecoverySalt);
    user.recoveryUsed = false;
    user.lastLoginAt = new Date().toISOString();

    this.saveLocalUsers(users);
    const session = this.setSession(user);
    this.syncUserToServer(user);

    return {
      success: true,
      user: session,
      newRecoveryCode: newRecoveryCode
    };
  }

  // --- サーバー（LAN）連携アカウント＆学習データ完全同期 ---

  static async fetchServerAccounts() {
    if (typeof window === 'undefined' || !window.fetch) return [];
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3000);
      const res = await fetch('/api/accounts', {
        method: 'GET',
        headers: { 'Accept': 'application/json' },
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      if (res.ok) {
        return await res.json();
      }
    } catch (_) {}
    return [];
  }

  static async fetchServerUserData(username) {
    if (typeof window === 'undefined' || !window.fetch || !username) return null;
    try {
      const clean = this.normalizeUsername(username);
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3000);
      const res = await fetch(`/api/sync/all?username=${encodeURIComponent(clean)}`, {
        method: 'GET',
        headers: { 'Accept': 'application/json' },
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      if (res.ok) {
        const data = await res.json();
        return (data && (data.username || data.account)) ? data : null;
      }
    } catch (_) {}
    return null;
  }

  static async syncUserToServer(user) {
    if (typeof window === 'undefined' || !user) return;
    
    // 1. Supabase クラウドへの自動プッシュ
    try {
      if (typeof SyncService !== 'undefined' && SyncService.pushAllLocalDataToCloud) {
        const config = SyncService.getConfig();
        if (config && config.supabaseUrl) {
          SyncService.pushAllLocalDataToCloud(config, user).catch(() => {});
        }
      }
    } catch (_) {}

    // 2. LAN内Webサーバーへのプッシュ（ローカルWi-Fi用）
    try {
      if (window.fetch) {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 3000);
        await fetch('/api/accounts/sync', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(user),
          signal: controller.signal
        });
        clearTimeout(timeoutId);
      }
    } catch (_) {}

    // 全データの同期も実行
    this.syncAllToServer(user.username);
  }

  static async syncAllToServer(username = null) {
    if (typeof window === 'undefined' || !window.fetch) return;
    const target = username || (this.getCurrentUser() ? this.getCurrentUser().username : null);
    if (!target) return;
    const clean = this.normalizeUsername(target);
    const users = this.getLocalUsers();
    const fullUser = users.find(u => this.normalizeUsername(u.username) === clean);

        // QRコード・トークン容量最適化メモ: 必要に応じた compact な slice(-10) 処理対応
    const payload = {
      username: clean,
      account: fullUser || null,
      storage: {
        gameStats: localStorage.getItem('mongol_app_game_stats_v1'),
        mistakes: localStorage.getItem('mongol_app_mistakes_v1'),
        wordProgress: localStorage.getItem('mongol_app_word_progress_v1'),
        lookedUpWords: localStorage.getItem('mongol_app_looked_up_words_v1'),
        history: localStorage.getItem('mongol_app_history_v1'),
        addedLaterWords: localStorage.getItem('mongol_app_added_later_words_v1'),
        dailyStats: localStorage.getItem('mongol_app_daily_stats_v1'),
        settings: localStorage.getItem('mongol_app_settings_v1'),
        customTyping: localStorage.getItem('mongol_app_custom_typing_sentences_v1'),
        sunglasses: localStorage.getItem('mongol_app_penguin_sunglasses_v1'),
        theme: localStorage.getItem('mongol_app_theme_mode_v1')
      },
      syncedAt: new Date().toISOString()
    };

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3500);
      await fetch('/api/sync/all', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        signal: controller.signal
      });
      clearTimeout(timeoutId);
    } catch (_) {}
  }

  static mergeServerUsers(serverUsers) {
    if (!Array.isArray(serverUsers)) return;
    const localUsers = this.getLocalUsers();
    let updated = false;

    serverUsers.forEach(su => {
      if (!su || !su.username) return;
      const clean = this.normalizeUsername(su.username);
      const idx = localUsers.findIndex(u => this.normalizeUsername(u.username) === clean);
      if (idx >= 0) {
        // 既存ユーザーの更新（最終ログイン時刻など）
        localUsers[idx] = { ...localUsers[idx], ...su };
        updated = true;
      } else {
        localUsers.push(su);
        updated = true;
      }
    });

    if (updated) {
      this.saveLocalUsers(localUsers);
    }
  }

  // --- 他端末（タブレット・スマホ）用ワンクリック URL 自動ログイン（Magic Login Token） ---

  /**
   * 現在のアカウント情報と学習ステータスからワンクリックログイン・QRコード・同期用トークンを生成
   * @param {Object} [user] 対象ユーザー（未指定時はログイン中ユーザー）
   * @param {boolean} [includeFullBackup=true] 完全バックアップ（間違いノート・単語進捗等）を含めるか
   */
  static createMagicLoginToken(user = null, includeFullBackup = true) {
    const targetUser = user || this.getCurrentUser();
    let cleanUsername = targetUser ? this.normalizeUsername(targetUser.username) : '';
    const users = this.getLocalUsers();
    let fullUser = users.find(u => this.normalizeUsername(u.username) === cleanUsername) || targetUser;

    if (!fullUser) {
      if (users.length > 0) {
        fullUser = users[0];
        cleanUsername = this.normalizeUsername(fullUser.username);
      } else {
        fullUser = {
          id: `usr_${Date.now()}`,
          username: 'pen',
          displayName: 'pen',
          createdAt: new Date().toISOString()
        };
      }
    }

    let mascotData = null;
    let gamificationData = null;
    let mistakesData = null;
    let lookedUpWordsData = null;
    let wordProgressData = null;
    let historyData = null;
    let dailyStatsData = null;
    let settingsData = null;
    let sunglassesData = null;
    let themeData = null;

    try {
      mascotData = localStorage.getItem('mongol_app_penguin_mascot_v1');
      gamificationData = localStorage.getItem('mongol_app_game_stats_v1') || localStorage.getItem('mongol_app_gamification_v2');
      mistakesData = localStorage.getItem('mongol_app_mistakes_v1');
      lookedUpWordsData = localStorage.getItem('mongol_app_looked_up_words_v1');
      wordProgressData = localStorage.getItem('mongol_app_word_progress_v1');
      historyData = localStorage.getItem('mongol_app_history_v1');
      dailyStatsData = localStorage.getItem('mongol_app_daily_stats_v1');
      settingsData = localStorage.getItem('mongol_app_settings_v1');
      sunglassesData = localStorage.getItem('mongol_app_penguin_sunglasses_v1');
      themeData = localStorage.getItem('mongol_app_theme_mode_v1');
    } catch (_) {}

    // クラウド設定（Supabase）があれば同梱
    let sbConfig = null;
    try {
      if (typeof SyncService !== 'undefined' && SyncService.getConfig) {
        const c = SyncService.getConfig();
        if (c && c.supabaseUrl && c.supabaseAnonKey) {
          sbConfig = {
            u: c.supabaseUrl,
            k: c.supabaseAnonKey
          };
        }
      }
    } catch (_) {}

    const payload = {
      v: 2,
      exportedAt: new Date().toISOString(),
      u: {
        id: fullUser.id || `usr_${Date.now()}`,
        username: fullUser.username,
        displayName: fullUser.displayName || fullUser.username,
        salt: fullUser.salt || '',
        passwordHash: fullUser.passwordHash || '',
        recoverySalt: fullUser.recoverySalt || '',
        recoveryCodeHash: fullUser.recoveryCodeHash || '',
        createdAt: fullUser.createdAt || new Date().toISOString()
      },
      g: gamificationData ? JSON.parse(gamificationData) : null,
      p: mascotData ? JSON.parse(mascotData) : null,
      m: mistakesData ? JSON.parse(mistakesData) : [],
      w: wordProgressData ? JSON.parse(wordProgressData) : {},
      l: lookedUpWordsData ? JSON.parse(lookedUpWordsData) : [],
      d: dailyStatsData ? JSON.parse(dailyStatsData) : null,
      s: {
        settings: settingsData ? JSON.parse(settingsData) : null,
        sunglasses: sunglassesData,
        theme: themeData
      },
      sb: sbConfig,
      t: Date.now()
    };

    try {
      const jsonStr = JSON.stringify(payload);
      const bytes = new TextEncoder().encode(jsonStr);
      let binary = '';
      for (let i = 0; i < bytes.length; i++) {
        binary += String.fromCharCode(bytes[i]);
      }
      return btoa(binary)
        .replace(/\+/g, '-')
        .replace(/\//g, '_')
        .replace(/=+$/, '');
    } catch (e) {
      console.error('[AuthService] createMagicLoginToken error:', e);
      try {
        return btoa(unescape(encodeURIComponent(JSON.stringify(payload))))
          .replace(/\+/g, '-')
          .replace(/\//g, '_')
          .replace(/=+$/, '');
      } catch (_) {
        return null;
      }
    }
  }

  /**
   * 指定ベースURLとアカウントから即時同期URLを生成
   * URLハッシュ(#sync=...)形式を採用し、サーバーのURL長制限やVercelの414/404エラーを回避
   */
  static createMagicLoginUrl(user, baseUrl) {
    const token = this.createMagicLoginToken(user);
    if (!token) return baseUrl;
    // URLハッシュ (#sync=...) はサーバーに一切送信されずブラウザ内だけで処理されるため安全
    const cleanBase = (baseUrl || window.location.href.split('#')[0].split('?')[0]).trim().replace(/\/+$/, '');
    return `${cleanBase}/#sync=${token}`;
  }

  /**
   * 任意の入力文字列（URL、ハッシュ、コード、改行混入、余分なクォートなど）からトークン/JSONを抽出・サニタイズ
   */
  static cleanAndExtractToken(rawInput) {
    if (!rawInput || typeof rawInput !== 'string') return '';
    let text = rawInput.trim();
    const trimmed = text;

    // 前後の引用符を除去
    text = text.replace(/^["'`]|["'`]$/g, '').trim();

    // 生のJSON形式の場合（{ で始まり } で終わる）はそのまま返却
    if (text.startsWith('{') && text.endsWith('}')) {
      return text;
    }

    // URL形式の場合のパラメータ/ハッシュ抽出
    if (/^https?:\/\//i.test(trimmed) || text.includes('#sync=') || text.includes('sync_token=') || text.includes('login_token=')) {
      // 1. ハッシュ(#sync=...)の抽出
      const hashMatch = text.match(/#sync=([^&\s]+)/i);
      if (hashMatch) return decodeURIComponent(hashMatch[1]).trim();

      // 2. クエリパラメータの抽出
      try {
        const u = new URL(text, (typeof window !== 'undefined' && window.location) ? window.location.origin : 'https://example.com');
        const t = u.searchParams.get('login_token') ||
                  u.searchParams.get('sync_token') ||
                  u.searchParams.get('auth_token') ||
                  u.searchParams.get('token') ||
                  u.searchParams.get('data');
        if (t) return decodeURIComponent(t).trim();
      } catch (_) {
        const qMatch = text.match(/[?&](?:login_token|sync_token|auth_token|token|data)=([^&\s#]+)/i);
        if (qMatch) return decodeURIComponent(qMatch[1]).trim();
      }

      // もしURL形式だが同期用トークンが一切含まれていない場合は空文字を返す（URLをトークンと誤認させない）
      if (/^https?:\/\//i.test(trimmed)) {
        return '';
      }
    }

    // プレフィックス(sync_token=, login_token= 等)が付いている場合の除去
    text = text.replace(/^(?:sync_token|login_token|auth_token|token|#sync)=\s*/i, '');

    // 改行、キャリッジリターン、タブ、余分なスペースを完全除去（Base64の健全性を保証）
    text = text.replace(/[\r\n\t\s]+/g, '');

    return text;
  }

  /**
   * あらゆる形式のバックアップ・同期ペイロードをローカルストレージへ確実に復元・マージする統一エンジン
   * @param {Object} payload パース済みデータオブジェクト
   */
  static applyUnifiedBackupPayload(payload) {
    if (!payload || typeof payload !== 'object') {
      return { success: false, error: '復元データが空または無効なオブジェクトです。' };
    }

    try {
      // 1. アカウント情報の復元 (payload.u または payload.account または payload.user)
      const u = payload.u || payload.account || payload.user || (payload.storage && payload.storage.account);
      let session = null;
      if (u && (u.username || u.displayName)) {
        const cleanUsername = this.normalizeUsername(u.username || u.displayName);
        const users = this.getLocalUsers();
        const existingIdx = users.findIndex(x => this.normalizeUsername(x.username) === cleanUsername);

        const userRecord = {
          id: u.id || `usr_${Date.now()}`,
          username: cleanUsername,
          displayName: u.displayName || u.username,
          salt: u.salt || '',
          passwordHash: u.passwordHash || '',
          recoverySalt: u.recoverySalt || '',
          recoveryCodeHash: u.recoveryCodeHash || '',
          createdAt: u.createdAt || new Date().toISOString(),
          lastLoginAt: new Date().toISOString()
        };

        if (existingIdx >= 0) {
          users[existingIdx] = { ...users[existingIdx], ...userRecord };
        } else {
          users.push(userRecord);
        }
        this.saveLocalUsers(users);
        session = this.setSession(userRecord);
      } else {
        session = this.getCurrentUser();
      }

      // 2. ゲームステータス・XP・称号の復元 (payload.g または payload.storage.gameStats または payload.gameStats)
      const gRaw = payload.g || (payload.storage && payload.storage.gameStats) || payload.gameStats;
      if (gRaw) {
        try {
          const incG = typeof gRaw === 'string' ? JSON.parse(gRaw) : gRaw;
          const curG = JSON.parse(localStorage.getItem('mongol_app_game_stats_v1') || '{}');
          // XPが大きい方を採用し、称号や最高コンボをマージ
          const mergedG = {
            ...curG,
            ...incG,
            totalXp: Math.max(Number(curG.totalXp) || 0, Number(incG.totalXp) || Number(incG.xp) || 0),
            level: Math.max(Number(curG.level) || 1, Number(incG.level) || 1),
            title: incG.title || curG.title || '大草原の語り部 🌾'
          };
          localStorage.setItem('mongol_app_game_stats_v1', JSON.stringify(mergedG));
          localStorage.setItem('mongol_app_gamification_v2', JSON.stringify(mergedG));
        } catch (_) {}
      }

      // 3. ペンギン育成ステータス (payload.p または payload.storage.mascot または payload.mascot)
      const pRaw = payload.p || (payload.storage && payload.storage.mascot) || payload.mascot;
      if (pRaw) {
        try {
          const incP = typeof pRaw === 'string' ? JSON.parse(pRaw) : pRaw;
          localStorage.setItem('mongol_app_penguin_mascot_v1', JSON.stringify(incP));
        } catch (_) {}
      }

      // 4. 間違いノート（全件復元・マージ） (payload.m または payload.storage.mistakes または payload.mistakes)
      const mRaw = payload.m || (payload.storage && payload.storage.mistakes) || payload.mistakes;
      let mistakesCount = 0;
      if (mRaw) {
        try {
          const incM = typeof mRaw === 'string' ? JSON.parse(mRaw) : mRaw;
          if (Array.isArray(incM)) {
            const curM = JSON.parse(localStorage.getItem('mongol_app_mistakes_v1') || '[]');
            incM.forEach(newItem => {
              const idx = curM.findIndex(x => x.id === newItem.id || (x.question === newItem.question && x.correctAnswer === newItem.correctAnswer));
              if (idx >= 0) {
                curM[idx] = { ...curM[idx], ...newItem };
              } else {
                curM.push(newItem);
              }
            });
            localStorage.setItem('mongol_app_mistakes_v1', JSON.stringify(curM));
            mistakesCount = curM.length;
          }
        } catch (_) {}
      }

      // 5. 単語学習進捗・SRSレベル (payload.w または payload.storage.wordProgress または payload.wordProgress)
      const wRaw = payload.w || (payload.storage && payload.storage.wordProgress) || payload.wordProgress;
      let wordsCount = 0;
      if (wRaw) {
        try {
          const incW = typeof wRaw === 'string' ? JSON.parse(wRaw) : wRaw;
          if (incW && typeof incW === 'object') {
            const curW = JSON.parse(localStorage.getItem('mongol_app_word_progress_v1') || '{}');
            Object.keys(incW).forEach(wId => {
              const incItem = incW[wId];
              const curItem = curW[wId];
              if (!curItem || (incItem && (incItem.srsLevel || 0) >= (curItem.srsLevel || 0))) {
                curW[wId] = { ...(curItem || {}), ...(incItem || {}) };
              }
            });
            localStorage.setItem('mongol_app_word_progress_v1', JSON.stringify(curW));
            wordsCount = Object.keys(curW).length;
          }
        } catch (_) {}
      }

      // 6. 調べた単語 (payload.l または payload.storage.lookedUpWords または payload.lookedUpWords)
      const lRaw = payload.l || (payload.storage && payload.storage.lookedUpWords) || payload.lookedUpWords;
      if (lRaw) {
        try {
          const incL = typeof lRaw === 'string' ? JSON.parse(lRaw) : lRaw;
          if (Array.isArray(incL)) {
            const curL = JSON.parse(localStorage.getItem('mongol_app_looked_up_words_v1') || '[]');
            incL.forEach(newItem => {
              const cleanKey = (newItem.dictForm || newItem.rawWord || '').trim().toLowerCase();
              const idx = curL.findIndex(x => (x.dictForm || x.rawWord || '').trim().toLowerCase() === cleanKey);
              if (idx >= 0) {
                curL[idx] = { ...curL[idx], ...newItem };
              } else {
                curL.push(newItem);
              }
            });
            localStorage.setItem('mongol_app_looked_up_words_v1', JSON.stringify(curL));
          }
        } catch (_) {}
      }

      // 7. デイリー統計・履歴・設定・サングラス・テーマ
      const sRaw = payload.s || payload.storage || {};
      try {
        if (payload.d || sRaw.dailyStats) {
          const d = payload.d || (typeof sRaw.dailyStats === 'string' ? JSON.parse(sRaw.dailyStats) : sRaw.dailyStats);
          if (d) localStorage.setItem('mongol_app_daily_stats_v1', JSON.stringify(d));
        }
        if (sRaw.settings) {
          const st = typeof sRaw.settings === 'string' ? JSON.parse(sRaw.settings) : sRaw.settings;
          if (st) localStorage.setItem('mongol_app_settings_v1', JSON.stringify(st));
        }
        if (sRaw.sunglasses) {
          localStorage.setItem('mongol_app_penguin_sunglasses_v1', String(sRaw.sunglasses));
        }
        if (sRaw.theme) {
          localStorage.setItem('mongol_app_theme_mode_v1', String(sRaw.theme));
        }
        if (sRaw.history) {
          const h = typeof sRaw.history === 'string' ? JSON.parse(sRaw.history) : sRaw.history;
          if (Array.isArray(h)) localStorage.setItem('mongol_app_history_v1', JSON.stringify(h));
        }
        if (sRaw.addedLaterWords || payload.addedLaterWords) {
          const rawA = sRaw.addedLaterWords || payload.addedLaterWords;
          const a = typeof rawA === 'string' ? JSON.parse(rawA) : rawA;
          if (Array.isArray(a)) {
            const curA = JSON.parse(localStorage.getItem('mongol_app_added_later_words_v1') || '[]');
            const mergedA = Array.from(new Set([...curA, ...a]));
            localStorage.setItem('mongol_app_added_later_words_v1', JSON.stringify(mergedA));
          }
        }
      } catch (_) {}

      // 8. 同梱されたSupabase設定があれば適用
      if (payload.sb && payload.sb.u && payload.sb.k) {
        try {
          if (typeof SyncService !== 'undefined' && SyncService.saveConfig) {
            SyncService.saveConfig({
              supabaseUrl: payload.sb.u,
              supabaseAnonKey: payload.sb.k,
              syncEnabled: true
            });
          }
        } catch (_) {}
      }

      console.log('[AuthService] Successfully applied unified backup payload:', {
        username: session ? session.username : 'guest',
        mistakesCount,
        wordsCount
      });

      return {
        success: true,
        user: session,
        stats: {
          mistakesCount,
          wordsCount
        }
      };
    } catch (err) {
      console.error('[AuthService] applyUnifiedBackupPayload error:', err);
      return { success: false, error: 'データ展開中にエラーが発生しました: ' + err.message };
    }
  }

  /**
   * 完全スナップショットのストレージ復元（互換性保持）
   */
  static restoreStorageSnapshot(storage) {
    if (!storage || typeof storage !== 'object') return;
    this.applyUnifiedBackupPayload({ storage });
  }

  /**
   * 学習データ・アカウントのバックアップJSON生成（ファイルダウンロード用）
   */
  static exportBackupData(user = null) {
    const targetUser = user || this.getCurrentUser();
    let clean = targetUser ? this.normalizeUsername(targetUser.username) : '';
    const users = this.getLocalUsers();
    let fullUser = users.find(u => this.normalizeUsername(u.username) === clean) || targetUser;

    if (!fullUser && users.length > 0) fullUser = users[0];

    return JSON.stringify({
      version: 2,
      exportedAt: new Date().toISOString(),
      account: fullUser || { username: 'pen', displayName: 'pen' },
      storage: {
        gameStats: localStorage.getItem('mongol_app_game_stats_v1'),
        mascot: localStorage.getItem('mongol_app_penguin_mascot_v1'),
        mistakes: localStorage.getItem('mongol_app_mistakes_v1'),
        wordProgress: localStorage.getItem('mongol_app_word_progress_v1'),
        lookedUpWords: localStorage.getItem('mongol_app_looked_up_words_v1'),
        history: localStorage.getItem('mongol_app_history_v1'),
        addedLaterWords: localStorage.getItem('mongol_app_added_later_words_v1'),
        dailyStats: localStorage.getItem('mongol_app_daily_stats_v1'),
        settings: localStorage.getItem('mongol_app_settings_v1'),
        customTyping: localStorage.getItem('mongol_app_custom_typing_sentences_v1'),
        sunglasses: localStorage.getItem('mongol_app_penguin_sunglasses_v1'),
        theme: localStorage.getItem('mongol_app_theme_mode_v1')
      }
    }, null, 2);
  }

  /**
   * バックアップJSONまたはBase64同期コードの読み込み・復元（超堅牢バリデーション対応）
   */
  static importBackupData(rawText) {
    if (!rawText || typeof rawText !== 'string') {
      return { success: false, error: 'データが空です。同期コードまたはURLを貼り付けてください。' };
    }

    const trimmed = rawText.trim();
    const cleaned = this.cleanAndExtractToken(rawText);

    if (!cleaned) {
      if (/^https?:\/\//i.test(trimmed)) {
        return {
          success: false,
          error: '貼り付けられたURLに同期用データ（login_token）が含まれていません。PCの「📱端末同期」画面で【同期コードのみコピー】を押してコードを貼り付けるか、スマホのカメラでQRコードを読み取ってください。'
        };
      }
      return { success: false, error: '有効な同期コードまたはURLが見つかりませんでした。' };
    }

    // 1. 生のJSON形式の場合（{ で始まり } で終わる）
    if (cleaned.startsWith('{') && cleaned.endsWith('}')) {
      try {
        const parsed = JSON.parse(cleaned);
        return this.applyUnifiedBackupPayload(parsed);
      } catch (err) {
        return { success: false, error: 'バックアップJSONの解析に失敗しました: ' + err.message };
      }
    }

    // 2. Base64形式の同期コード（eyJ2Ijoy... または URLセーフBase64）のデコード
    try {
      let b64 = cleaned.replace(/-/g, '+').replace(/_/g, '/');
      while (b64.length % 4 !== 0) {
        b64 += '=';
      }

      let jsonStr = '';
      try {
        const binary = atob(b64);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) {
          bytes[i] = binary.charCodeAt(i);
        }
        jsonStr = new TextDecoder('utf-8').decode(bytes);
      } catch (_) {
        // TextDecoderフォールバック
        jsonStr = decodeURIComponent(escape(atob(b64)));
      }

      if (jsonStr && jsonStr.startsWith('{') && jsonStr.endsWith('}')) {
        const payload = JSON.parse(jsonStr);
        return this.applyUnifiedBackupPayload(payload);
      }
    } catch (e) {
      console.warn('[AuthService] Base64 decode attempt 1 failed:', e);
    }

    // 3. processMagicLoginToken でのフォールバック
    const res = this.processMagicLoginToken(cleaned);
    if (res.success) return res;

    return {
      success: false,
      error: '同期コードの解析に失敗しました。コードが途中で切れていないか確認し、PC画面の【同期コードのみコピー】を再度お試しください。'
    };
  }

  /**
   * ワンクリックログインURLのトークンを解析してアカウントを登録・自動ログイン（互換性確保）
   */
  static processMagicLoginToken(token) {
    if (!token) return { success: false, error: 'トークンが空です。' };

    const cleaned = this.cleanAndExtractToken(token);
    try {
      let b64 = cleaned.replace(/-/g, '+').replace(/_/g, '/');
      while (b64.length % 4 !== 0) {
        b64 += '=';
      }

      let jsonStr = '';
      try {
        const binary = atob(b64);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) {
          bytes[i] = binary.charCodeAt(i);
        }
        jsonStr = new TextDecoder('utf-8').decode(bytes);
      } catch (_) {
        jsonStr = decodeURIComponent(escape(atob(b64)));
      }

      const payload = JSON.parse(jsonStr);
      return this.applyUnifiedBackupPayload(payload);
    } catch (e) {
      console.error('[AuthService] processMagicLoginToken error:', e);
      return {
        success: false,
        error: '同期コードの形式が無効です。コード全体をコピーして貼り付けてください。'
      };
    }
  }

  /**
   * 他端末ログイン成功時のトースト通知バナー
   */
  static showLoginSuccessToast(username) {
    let toast = document.getElementById('magic-login-toast');
    if (!toast) {
      toast = document.createElement('div');
      toast.id = 'magic-login-toast';
      document.body.appendChild(toast);
    }

    toast.className = "fixed top-4 left-1/2 -translate-x-1/2 z-[99999] max-w-sm w-11/12 bg-gradient-to-r from-emerald-600 to-teal-700 text-white px-4 py-3 rounded-2xl shadow-xl flex items-center gap-3 animate-fade-in border border-emerald-400";
    toast.innerHTML = `
      <span class="text-2xl animate-bounce">🐧</span>
      <div class="flex-1 min-w-0">
        <div class="text-xs font-bold leading-tight">ログイン完了！</div>
        <div class="text-[11px] opacity-90 truncate">「${username}」のアカウントを連携しました</div>
      </div>
      <button type="button" class="text-white/80 hover:text-white font-bold p-1 text-sm" onclick="this.parentElement.remove()">✕</button>
    `;

    setTimeout(() => {
      if (toast && toast.parentElement) {
        toast.style.transition = 'opacity 0.5s ease';
        toast.style.opacity = '0';
        setTimeout(() => toast.remove(), 500);
      }
    }, 4500);
  }
  /**
   * ペアリング完了通知をホスト端末（PC）へ送信（マルチチャネル：API・BroadcastChannel・LocalStorage）
   */
  static notifyPairSuccess(sessionId, user) {
    if (!sessionId) return;
    const deviceName = typeof navigator !== 'undefined'
      ? (/iPad/.test(navigator.userAgent) ? 'iPad' :
         /iPhone/.test(navigator.userAgent) ? 'iPhone' :
         /Android/.test(navigator.userAgent) ? 'Android端末' : 'モバイル端末')
      : 'モバイル端末';

    const payload = {
      sessionId,
      username: user ? user.username : '',
      displayName: user ? (user.displayName || user.username) : '',
      device: deviceName,
      timestamp: Date.now()
    };

    // 1. ローカルサーバーAPI送信 (LAN経由の異端末間同期)
    try {
      fetch('/api/sync/pair', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      }).catch(() => {});
    } catch (_) {}

    // 2. BroadcastChannel送信 (同一ブラウザ/PWA間)
    try {
      if (typeof BroadcastChannel !== 'undefined') {
        const bc = new BroadcastChannel('mongol_app_sync_channel');
        bc.postMessage(payload);
        setTimeout(() => { try { bc.close(); } catch(_) {} }, 1000);
      }
    } catch (_) {}

    // 3. StorageEvent発火 (他タブ/ウィンドウ検知)
    try {
      localStorage.setItem('mongol_app_last_pair_event', JSON.stringify(payload));
    } catch (_) {}
  }

  /**
   * ホスト側でペアリング完了状態を確認
   */
  static async checkPairStatus(sessionId) {
    if (!sessionId) return { status: 'waiting' };
    try {
      const res = await fetch(`/api/sync/pair/status?sessionId=${encodeURIComponent(sessionId)}`, {
        cache: 'no-store'
      });
      if (res.ok) {
        return await res.json();
      }
    } catch (_) {}
    return { status: 'waiting' };
  }

  /**
   * ホスト側でセッションデータを登録（軽量QR用）
   */
  static async registerPairSession(sessionId, user, token) {
    if (!sessionId || !user) return;
    try {
      await fetch('/api/sync/pair/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId,
          username: user.username,
          displayName: user.displayName || user.username,
          token,
          createdAt: Date.now()
        })
      });
    } catch (_) {}
  }
}


// === js/services/sync.js ===
// クラウド同期・オフラインキューサービス（Supabase REST / LocalStorage ハイブリッド）


// アプリ公式 Supabase クラウド初期設定（手動入力不要で全端末が即時同期可能）
const DEFAULT_SUPABASE_CONFIG = {
  supabaseUrl: 'https://hwmfxtgnhahjgpziczic.supabase.co',
  supabaseAnonKey: 'sb_publishable_Win4LjLX9fBwruCa9etB8Q_yQZ-Sa7F',
  syncEnabled: true
};

class SyncService {
  /**
   * Supabase URL をサニタイズ（末尾の /rest/v1 や余分なスラッシュを自動除去）
   */
  static cleanSupabaseUrl(rawUrl) {
    if (!rawUrl || typeof rawUrl !== 'string') return '';
    let u = rawUrl.trim();
    // 誤字（hwmn -> hwmf）の自動補正
    u = u.replace(/hwmnxtgnhahjgpziczic/g, 'hwmfxtgnhahjgpziczic');
    // 末尾の /rest/v1/ や /rest/v1 を徹底除去
    u = u.replace(/\/rest\/v1\/?$/i, '');
    u = u.replace(/\/+$/, '');
    if (u && !u.startsWith('http://') && !u.startsWith('https://')) {
      u = 'https://' + u;
    }
    return u;
  }
  static CONFIG_KEY = 'mongol_app_cloud_config_v1';
  static QUEUE_KEY = 'mongol_app_sync_queue_v1';
  static LAST_SYNC_KEY = 'mongol_app_last_sync_time_v1';

  static state = {
    status: 'local_only', // 'synced' | 'syncing' | 'offline' | 'local_only' | 'error'
    lastSyncTime: null,
    pendingCount: 0,
    errorMessage: null,
    listeners: []
  };

  /**
   * クラウド設定を取得（ユーザー入力またはグローバル設定）
   */
  static getConfig() {
    try {
      const stored = localStorage.getItem(this.CONFIG_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed && parsed.supabaseUrl) {
          parsed.supabaseUrl = this.cleanSupabaseUrl(parsed.supabaseUrl);
          return parsed;
        }
      }
      if (typeof window !== 'undefined' && window.MONGOL_APP_CONFIG) {
        const c = window.MONGOL_APP_CONFIG;
        c.supabaseUrl = this.cleanSupabaseUrl(c.supabaseUrl);
        return c;
      }
      // デフォルト設定を返却（全端末で初期設定なしでも即使えるようにする）
      return { ...DEFAULT_SUPABASE_CONFIG };
    } catch (e) {
      return { ...DEFAULT_SUPABASE_CONFIG };
    }
  }

  static saveConfig(config) {
    if (config) {
      const sanitized = {
        ...config,
        supabaseUrl: this.cleanSupabaseUrl(config.supabaseUrl)
      };
      localStorage.setItem(this.CONFIG_KEY, JSON.stringify(sanitized));
    } else {
      localStorage.removeItem(this.CONFIG_KEY);
    }
    this.updateStatus();
  }

  static isCloudConfigured() {
    const config = this.getConfig();
    return Boolean(config && config.supabaseUrl && config.supabaseAnonKey);
  }

  /**
   * 初期化: ネットワーク監視とキューの自動送信リスナーを設定
   */
  static init(onStatusChange) {
    if (onStatusChange) this.addListener(onStatusChange);

    this.state.lastSyncTime = localStorage.getItem(this.LAST_SYNC_KEY);
    this.state.pendingCount = this.getQueue().length;

    // オンライン・オフラインイベント監視
    if (typeof window !== 'undefined') {
      window.addEventListener('online', () => {
        console.log('[SyncService] Network restored. Attempting auto-sync...');
        this.triggerSync();
      });

      window.addEventListener('offline', () => {
        this.updateStatus('offline');
      });
    }

    this.updateStatus();

    // 起動時の自動同期
    if (this.isCloudConfigured() && navigator.onLine) {
      setTimeout(() => this.triggerSync(), 800);
    }

    // 常時同期: タブ復帰時（画面アンロック・他タブから戻った時）に即時同期
    if (typeof window !== 'undefined' && typeof document !== 'undefined') {
      document.addEventListener('visibilitychange', () => {
        if (!document.hidden && navigator.onLine) {
          this.triggerSync();
        }
      });
      window.addEventListener('focus', () => {
        if (navigator.onLine) {
          this.triggerSync();
        }
      });
      // 15秒ごとのバックグラウンド定期同期（アクティブ時）
      setInterval(() => {
        if (!document.hidden && navigator.onLine) {
          this.triggerSync();
        }
      }, 15000);
    }
  }

  static addListener(fn) {
    this.state.listeners.push(fn);
    fn(this.state);
  }

  static notifyListeners() {
    this.state.listeners.forEach(fn => fn({ ...this.state }));
  }

  static updateStatus(overrideStatus = null) {
    const isOnline = typeof navigator !== 'undefined' ? navigator.onLine : true;
    const isConfigured = this.isCloudConfigured();
    const user = AuthService.getCurrentUser();

    if (!isConfigured || !user) {
      this.state.status = 'local_only';
    } else if (!isOnline) {
      this.state.status = 'offline';
    } else if (overrideStatus) {
      this.state.status = overrideStatus;
    } else if (this.getQueue().length > 0) {
      this.state.status = 'offline'; // 未同期アイテムあり
    } else {
      this.state.status = 'synced';
    }

    this.state.pendingCount = this.getQueue().length;
    this.notifyListeners();
  }

  // --- オフライン同期キュー管理 ---

  static getQueue() {
    try {
      const data = localStorage.getItem(this.QUEUE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  static saveQueue(queue) {
    localStorage.setItem(this.QUEUE_KEY, JSON.stringify(queue));
    this.state.pendingCount = queue.length;
    this.notifyListeners();
  }

  /**
   * 同期キューにアクションを追加（オフライン・オンライン問わず即時記録）
   * @param {string} actionType 'UPDATE_WORD_PROGRESS' | 'RECORD_MISTAKE' | 'RESOLVE_MISTAKE' | 'RECORD_HISTORY' | 'UPDATE_SETTINGS'
   * @param {Object} payload 変更データ
   */
  static enqueueChange(actionType, payload) {
    const queue = this.getQueue();
    queue.push({
      id: `sync_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
      action: actionType,
      payload: payload,
      timestamp: new Date().toISOString()
    });
    this.saveQueue(queue);

    // オンラインかつ設定済ならバックグラウンド同期をトリガー
    if (navigator.onLine && this.isCloudConfigured() && AuthService.getCurrentUser()) {
      this.triggerSync();
    }
  }

  // --- 同期処理の実行 ---

  static isSyncing = false;

    static syncDebounceTimer = null;
  /**
   * 学習データ変更時の自動プッシュ通知（デバウンス1秒でSupabaseへ常時同期）
   */
  static notifyDataChanged() {
    if (this.syncDebounceTimer) clearTimeout(this.syncDebounceTimer);
    this.syncDebounceTimer = setTimeout(() => {
      this.triggerSync();
    }, 1200);
  }

  static async triggerSync() {
    if (this.isSyncing) return;
    const config = this.getConfig();
    const user = AuthService.getCurrentUser();

    // 1. ローカルWebサーバー（LAN内）へ常に自動バックグラウンド同期
    try {
      if (user && navigator.onLine && typeof AuthService.syncAllToServer === 'function') {
        AuthService.syncAllToServer(user.username);
      }
    } catch (_) {}

    const activeUser = user || AuthService.getCurrentUser() || {
      id: 'usr_1793885321289_e34dbfca',
      username: 'pen',
      displayName: 'pen'
    };

    if (!config || !navigator.onLine) {
      this.updateStatus();
      return;
    }

    this.isSyncing = true;
    this.updateStatus('syncing');

    try {
      // 1. まずクラウドの最新データを取得してローカルにマージ（高いXPや進捗を優先保護）
      await this.pullFromCloud(config, activeUser);

      // 2. 保留中キューの送信
      await this.flushQueue(config, activeUser);

      // 3. マージ後の最新データをクラウドへプッシュ（最高ステータスをクラウドに同期）
      await this.pushAllLocalDataToCloud(config, activeUser);

      const now = new Date().toISOString();
      this.state.lastSyncTime = now;
      localStorage.setItem(this.LAST_SYNC_KEY, now);
      this.state.errorMessage = null;
      this.updateStatus('synced');
    } catch (err) {
      console.warn('[SyncService] Sync warning/error:', err);
      this.state.errorMessage = err.message || '同期中に一時的な通信エラーが発生しました。';
      this.updateStatus(navigator.onLine ? 'error' : 'offline');
    } finally {
      this.isSyncing = false;
    }
  }

  /**
   * ローカルキューをSupabaseへ一括送信
   */
  static async flushQueue(config, user) {
    const queue = this.getQueue();
    if (queue.length === 0) return;

    const remainingQueue = [];
    const url = this.cleanSupabaseUrl(config.supabaseUrl);
    const headers = {
      'apikey': config.supabaseAnonKey,
      'Authorization': `Bearer ${config.supabaseAnonKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'resolution=merge-duplicates'
    };

    for (const item of queue) {
      try {
        if (item.action === 'UPDATE_WORD_PROGRESS') {
          const prog = item.payload;
          const body = {
            user_id: user.id,
            word_id: prog.wordId,
            srs_level: prog.srsLevel,
            interval_days: prog.intervalDays,
            next_review_date: prog.nextReviewDate,
            last_learned_at: prog.lastLearnedAt,
            study_count: prog.studyCount,
            correct_count: prog.correctCount,
            wrong_count: prog.wrongCount,
            accuracy: prog.accuracy,
            updated_at: prog.updatedAt || new Date().toISOString()
          };

          const res = await fetch(`${url}/rest/v1/user_word_progress`, {
            method: 'POST',
            headers,
            body: JSON.stringify(body)
          });
          if (!res.ok && res.status !== 409) {
            throw new Error(`Progress sync failed: ${res.statusText}`);
          }
        } else if (item.action === 'RECORD_MISTAKE') {
          const m = item.payload;
          const body = {
            id: m.id,
            user_id: user.id,
            question: m.question,
            correct_answer: m.correctAnswer,
            user_answer: m.userAnswer,
            type: m.type || 'word',
            category: m.category || '全般',
            explanation: m.explanation || '',
            wrong_count: m.wrongCount || 1,
            last_wrong_date: m.lastWrongDate || new Date().toISOString(),
            resolved: Boolean(m.resolved || ((m.consecutiveCorrect || 0) >= 3)),
            updated_at: new Date().toISOString()
          };

          const res = await fetch(`${url}/rest/v1/user_mistakes`, {
            method: 'POST',
            headers,
            body: JSON.stringify(body)
          });
          if (!res.ok && res.status !== 409) {
            throw new Error(`Mistake sync failed: ${res.statusText}`);
          }
        } else if (item.action === 'RECORD_HISTORY') {
          const h = item.payload;
          const body = {
            id: h.id,
            user_id: user.id,
            type: h.type || 'word',
            total: h.total,
            correct: h.correct,
            category: h.category || '',
            mode: h.mode || '',
            timestamp: h.timestamp || new Date().toISOString()
          };

          const res = await fetch(`${url}/rest/v1/user_history`, {
            method: 'POST',
            headers,
            body: JSON.stringify(body)
          });
          if (!res.ok && res.status !== 409) {
            throw new Error(`History sync failed: ${res.statusText}`);
          }
        }
      } catch (e) {
        console.warn(`[SyncService] Queue item failed, keeping in queue:`, item, e);
        remainingQueue.push(item);
      }
    }

    this.saveQueue(remainingQueue);
  }

  /**
   * クラウド上の最新進捗をダウンロードし、ローカルデータと統合
   */
  static async pullFromCloud(config, user = null) {
    const url = this.cleanSupabaseUrl(config.supabaseUrl);
    const headers = {
      'apikey': config.supabaseAnonKey,
      'Authorization': `Bearer ${config.supabaseAnonKey}`,
      'Accept': 'application/json'
    };

    // 1. 単語進捗の取得
    try {
      let progEndpoint = `${url}/rest/v1/user_word_progress?select=*&limit=1000`;
      if (user && user.id) {
        progEndpoint = `${url}/rest/v1/user_word_progress?user_id=eq.${user.id}`;
      }
      const res = await fetch(progEndpoint, { headers });
      if (res.ok) {
        const rows = await res.json();
        if (Array.isArray(rows) && rows.length > 0) {
          const localMap = JSON.parse(localStorage.getItem('mongol_app_word_progress_v1') || '{}');
          rows.forEach(r => {
            const existing = localMap[r.word_id];
            // 更新日時または学習回数が進んでいる方を採用
            if (!existing || new Date(r.updated_at) >= new Date(existing.updatedAt || 0)) {
              localMap[r.word_id] = {
                wordId: r.word_id,
                srsLevel: r.srs_level,
                intervalDays: r.interval_days,
                nextReviewDate: r.next_review_date,
                lastLearnedAt: r.last_learned_at,
                studyCount: r.study_count,
                correctCount: r.correct_count,
                wrongCount: r.wrong_count,
                accuracy: r.accuracy,
                updatedAt: r.updated_at
              };
            }
          });
          localStorage.setItem('mongol_app_word_progress_v1', JSON.stringify(localMap));
        }
      }
    } catch (e) {
      console.warn('[SyncService] Pull progress failed:', e);
    }

    // 2. 間違いノートの取得
    try {
      let mistEndpoint = `${url}/rest/v1/user_mistakes?select=*&limit=1000`;
      if (user && user.id) {
        mistEndpoint = `${url}/rest/v1/user_mistakes?user_id=eq.${user.id}`;
      }
      const res = await fetch(mistEndpoint, { headers });
      if (res.ok) {
        const rows = await res.json();
        if (Array.isArray(rows) && rows.length > 0) {
          const localMistakes = JSON.parse(localStorage.getItem('mongol_app_mistakes_v1') || '[]');
          rows.forEach(r => {
            const idx = localMistakes.findIndex(m => m.id === r.id || (m.question === r.question && m.correctAnswer === r.correct_answer));
            const cloudItem = {
              id: r.id,
              question: r.question,
              correctAnswer: r.correct_answer,
              userAnswer: r.user_answer,
              type: r.type,
              category: r.category,
              explanation: r.explanation,
              wrongCount: r.wrong_count || 1,
              lastWrongDate: r.last_wrong_date || r.created_at,
              resolved: Boolean(r.resolved)
            };
            if (idx !== -1) {
              const localItem = localMistakes[idx];
              cloudItem.wrongCount = Math.max(cloudItem.wrongCount, localItem.wrongCount || 1);
              // ローカルの連続正解数・克服状態を保護（クラウドからの上書きリセットを防止）
              cloudItem.consecutiveCorrect = localItem.consecutiveCorrect !== undefined 
                ? localItem.consecutiveCorrect 
                : (cloudItem.resolved ? 3 : 0);
              cloudItem.resolved = Boolean(cloudItem.resolved || localItem.resolved || (cloudItem.consecutiveCorrect >= 3));
              if (localItem.resolvedAt && !cloudItem.resolvedAt) {
                cloudItem.resolvedAt = localItem.resolvedAt;
              }
              localMistakes[idx] = { ...localItem, ...cloudItem };
            } else {
              cloudItem.consecutiveCorrect = cloudItem.resolved ? 3 : 0;
              localMistakes.push(cloudItem);
            }
          });
          localStorage.setItem('mongol_app_mistakes_v1', JSON.stringify(localMistakes));
          // 画面へ更新通知を発火
          try {
            if (typeof window !== 'undefined') {
              window.dispatchEvent(new CustomEvent('mongol_app_mistakes_updated'));
            }
          } catch (_) {}
        }
      }
    } catch (e) {
      console.warn('[SyncService] Pull mistakes failed:', e);
    }

    // 3. 万能スナップショットからの取得（最新の全学習データを即時統合）
    try {
      let snapEndpoint = `${url}/rest/v1/user_sync_snapshot?order=updated_at.desc&limit=1`;
      if (user && user.username) {
        snapEndpoint = `${url}/rest/v1/user_sync_snapshot?username=eq.${encodeURIComponent(user.username)}&order=updated_at.desc&limit=1`;
      }
      const res = await fetch(snapEndpoint, { headers });
      if (res.ok) {
        const rows = await res.json();
        if (Array.isArray(rows) && rows.length > 0 && rows[0].payload) {
          const snap = rows[0].payload;
          
          // アカウントの自動復元
          if (snap.account && typeof AuthService !== 'undefined') {
            try {
              AuthService.mergeServerUsers([snap.account]);
              const curUser = AuthService.getCurrentUser();
              if (!curUser || curUser.username !== snap.account.username) {
                AuthService.setSession(snap.account);
              }
            } catch (_) {}
          }

          // 間違いノートの復元
          if (Array.isArray(snap.mistakes) && snap.mistakes.length > 0) {
            const currentMistakes = JSON.parse(localStorage.getItem('mongol_app_mistakes_v1') || '[]');
            snap.mistakes.forEach(m => {
              const idx = currentMistakes.findIndex(x => x.id === m.id || (x.question === m.question && x.correctAnswer === m.correctAnswer));
              if (idx === -1) {
                currentMistakes.push(m);
              } else {
                const local = currentMistakes[idx];
                const isResolved = Boolean(local.resolved || m.resolved || ((local.consecutiveCorrect || 0) >= 3) || ((m.consecutiveCorrect || 0) >= 3));
                const consecutive = Math.max(local.consecutiveCorrect || 0, m.consecutiveCorrect || 0);
                currentMistakes[idx] = {
                  ...m,
                  ...local,
                  consecutiveCorrect: isResolved ? Math.max(consecutive, 3) : consecutive,
                  resolved: isResolved
                };
              }
            });
            localStorage.setItem('mongol_app_mistakes_v1', JSON.stringify(currentMistakes));
          }

          // 単語進捗の復元（両キー対応）
          if (snap.wordProgress && typeof snap.wordProgress === 'object') {
            const curProg = JSON.parse(localStorage.getItem('mongol_app_word_progress_v1') || '{}');
            Object.assign(curProg, snap.wordProgress);
            localStorage.setItem('mongol_app_word_progress_v1', JSON.stringify(curProg));
          }
          if (snap.srsProgress && typeof snap.srsProgress === 'object') {
            const curSrs = JSON.parse(localStorage.getItem('mongol_app_srs_progress_v1') || '{}');
            Object.assign(curSrs, snap.srsProgress);
            localStorage.setItem('mongol_app_srs_progress_v1', JSON.stringify(curSrs));
          }

          // ゲーム統計・XP・レベル・称号の完全復元
          if (snap.gameStats && typeof snap.gameStats === 'object') {
            const curStats = JSON.parse(localStorage.getItem('mongol_app_game_stats_v1') || '{}');
            const merged = { ...curStats, ...snap.gameStats };
            // より高いXP・レベルを維持
            if (snap.gameStats.totalXp && (!curStats.totalXp || snap.gameStats.totalXp > curStats.totalXp)) {
              merged.totalXp = snap.gameStats.totalXp;
              merged.level = snap.gameStats.level;
              merged.currentTitle = snap.gameStats.currentTitle;
            }
            localStorage.setItem('mongol_app_game_stats_v1', JSON.stringify(merged));
          }

          // ペンギンマスコット育成・称号の復元
          if (snap.mascot && typeof snap.mascot === 'object') {
            localStorage.setItem('mongol_app_penguin_mascot_v1', JSON.stringify(snap.mascot));
          }
          if (snap.penguinMascot && typeof snap.penguinMascot === 'object') {
            localStorage.setItem('mongol_app_penguin_mascot_v1', JSON.stringify(snap.penguinMascot));
          }

          // 日別学習目標・進捗の復元
          if (snap.dailyStats && typeof snap.dailyStats === 'object') {
            localStorage.setItem('mongol_app_daily_stats_v1', JSON.stringify(snap.dailyStats));
          }

          // 単語ファミリー進捗・追加語形の同期マージ
          if (snap.wordFamilyProgress && typeof snap.wordFamilyProgress === 'object') {
            const curFam = JSON.parse(localStorage.getItem('mongol_app_word_family_progress_v1') || '{}');
            for (const [formId, formProg] of Object.entries(snap.wordFamilyProgress)) {
              if (!curFam[formId] || (formProg.studyCount || 0) > (curFam[formId].studyCount || 0) || formProg.mastered) {
                curFam[formId] = formProg;
              }
            }
            localStorage.setItem('mongol_app_word_family_progress_v1', JSON.stringify(curFam));
          }
          if (Array.isArray(snap.addedFamilyIds)) {
            const curIds = JSON.parse(localStorage.getItem('mongol_app_added_family_ids_v1') || '[]');
            const mergedIds = Array.from(new Set([...curIds, ...snap.addedFamilyIds]));
            localStorage.setItem('mongol_app_added_family_ids_v1', JSON.stringify(mergedIds));
          }
          if (Array.isArray(snap.addedFamilyFormIds)) {
            const curFormIds = JSON.parse(localStorage.getItem('mongol_app_added_family_form_ids_v1') || '[]');
            const mergedFormIds = Array.from(new Set([...curFormIds, ...snap.addedFamilyFormIds]));
            localStorage.setItem('mongol_app_added_family_form_ids_v1', JSON.stringify(mergedFormIds));
          }

          // あとで覚える単語（ゲーム追加単語）のクラウド同期マージ
          if (Array.isArray(snap.addedLaterWords) && snap.addedLaterWords.length > 0) {
            const currentAdded = JSON.parse(localStorage.getItem('mongol_app_added_later_words_v1') || '[]');
            const mergedAdded = Array.from(new Set([...currentAdded, ...snap.addedLaterWords]));
            localStorage.setItem('mongol_app_added_later_words_v1', JSON.stringify(mergedAdded));
          }

          // 後で覚える単語へ移動（退避）した単語のクラウド同期マージ
          if (Array.isArray(snap.demotedToLaterWords) && snap.demotedToLaterWords.length > 0) {
            const currentDemoted = JSON.parse(localStorage.getItem('mongol_app_demoted_to_later_words_v1') || '[]');
            const mergedDemoted = Array.from(new Set([...currentDemoted, ...snap.demotedToLaterWords]));
            localStorage.setItem('mongol_app_demoted_to_later_words_v1', JSON.stringify(mergedDemoted));
          }

          try {
            if (typeof window !== 'undefined') {
              window.dispatchEvent(new CustomEvent('mongol_app_mistakes_updated'));
              window.dispatchEvent(new CustomEvent('mongol_app_storage_updated'));
            }
          } catch (_) {}
        }
      }
    } catch (e) {
      console.warn('[SyncService] Pull user_sync_snapshot failed:', e);
    }
  }

  /**
   * ローカルに蓄積されている全学習データ（アカウント、間違えた問題、単語進捗、履歴）をSupabaseへ一括プッシュ
   */
  static async pushAllLocalDataToCloud(config, user) {
    if (!config || !user || !config.supabaseUrl || !config.supabaseAnonKey) return;
    const url = this.cleanSupabaseUrl(config.supabaseUrl);
    const headers = {
      'apikey': config.supabaseAnonKey,
      'Authorization': `Bearer ${config.supabaseAnonKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'resolution=merge-duplicates'
    };

    // 1. アカウント情報のUPSERT
    try {
      const accountBody = {
        id: user.id,
        username: user.username,
        display_name: user.displayName || user.username,
        salt: user.salt || '',
        password_hash: user.passwordHash || '',
        recovery_salt: user.recoverySalt || '',
        recovery_code_hash: user.recoveryCodeHash || '',
        last_login_at: new Date().toISOString()
      };
      await fetch(`${url}/rest/v1/user_accounts`, {
        method: 'POST',
        headers,
        body: JSON.stringify(accountBody)
      });
    } catch (e) {
      console.warn('[SyncService] Push user_accounts failed:', e);
    }

    // 2. 間違えた問題（全件）のUPSERT
    try {
      const mistakes = JSON.parse(localStorage.getItem('mongol_app_mistakes_v1') || '[]');
      if (Array.isArray(mistakes) && mistakes.length > 0) {
        for (let i = 0; i < mistakes.length; i += 50) {
          const chunk = mistakes.slice(i, i + 50).map(m => ({
            id: m.id || `m_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
            user_id: user.id,
            question: m.question || '',
            correct_answer: m.correctAnswer || '',
            user_answer: m.userAnswer || '',
            type: m.type || 'word',
            category: m.category || '単語',
            explanation: m.explanation || '',
            wrong_count: m.wrongCount || 1,
            last_wrong_date: m.lastWrongDate || new Date().toISOString(),
            resolved: Boolean(m.resolved || ((m.consecutiveCorrect || 0) >= 3)),
            updated_at: new Date().toISOString()
          }));
          await fetch(`${url}/rest/v1/user_mistakes`, {
            method: 'POST',
            headers,
            body: JSON.stringify(chunk)
          });
        }
      }
    } catch (e) {
      console.warn('[SyncService] Push user_mistakes failed:', e);
    }

    // 3. 単語進捗（全件）のUPSERT
    try {
      const progMap = JSON.parse(localStorage.getItem('mongol_app_word_progress_v1') || '{}');
      const progList = Object.values(progMap);
      if (progList.length > 0) {
        for (let i = 0; i < progList.length; i += 50) {
          const chunk = progList.slice(i, i + 50).map(p => ({
            user_id: user.id,
            word_id: p.wordId || p.id,
            srs_level: p.srsLevel || 0,
            interval_days: p.intervalDays || 0,
            next_review_date: p.nextReviewDate || null,
            last_learned_at: p.lastLearnedAt || new Date().toISOString(),
            study_count: p.studyCount || 1,
            correct_count: p.correctCount || 0,
            wrong_count: p.wrongCount || 0,
            accuracy: p.accuracy || 0,
            updated_at: p.updatedAt || new Date().toISOString()
          }));
          await fetch(`${url}/rest/v1/user_word_progress`, {
            method: 'POST',
            headers,
            body: JSON.stringify(chunk)
          });
        }
      }
    } catch (e) {
      console.warn('[SyncService] Push user_word_progress failed:', e);
    }

    // 4. 学習履歴のUPSERT
    try {
      const history = JSON.parse(localStorage.getItem('mongol_app_history_v1') || '[]');
      if (Array.isArray(history) && history.length > 0) {
        const recentHistory = history.slice(-50);
        const chunk = recentHistory.map(h => ({
          id: h.id || `h_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
          user_id: user.id,
          type: h.type || 'word',
          total: h.total || 0,
          correct: h.correct || 0,
          category: h.category || '',
          mode: h.mode || '',
          timestamp: h.timestamp || new Date().toISOString()
        }));
        await fetch(`${url}/rest/v1/user_history`, {
          method: 'POST',
          headers,
          body: JSON.stringify(chunk)
        });
      }
    } catch (e) {
      console.warn('[SyncService] Push user_history failed:', e);
    }

    // 5. 万能スナップショットのUPSERT（全学習データまるごと即時同期フォールバック）
    try {
      const fullSnapshot = {
        user_id: user.id,
        username: user.username,
        updated_at: new Date().toISOString(),
        payload: {
          account: user,
          mistakes: JSON.parse(localStorage.getItem('mongol_app_mistakes_v1') || '[]'),
          wordProgress: JSON.parse(localStorage.getItem('mongol_app_word_progress_v1') || '{}'),
          srsProgress: JSON.parse(localStorage.getItem('mongol_app_srs_progress_v1') || '{}'),
          gameStats: JSON.parse(localStorage.getItem('mongol_app_game_stats_v1') || '{}'),
          dailyStats: JSON.parse(localStorage.getItem('mongol_app_daily_stats_v1') || '{}'),
          mascot: JSON.parse(localStorage.getItem('mongol_app_penguin_mascot_v1') || '{}'),
          penguinMascot: JSON.parse(localStorage.getItem('mongol_app_penguin_mascot_v1') || '{}'),
          history: JSON.parse(localStorage.getItem('mongol_app_history_v1') || '[]'),
          addedLaterWords: JSON.parse(localStorage.getItem('mongol_app_added_later_words_v1') || '[]'),
          demotedToLaterWords: JSON.parse(localStorage.getItem('mongol_app_demoted_to_later_words_v1') || '[]')
        }
      };
      await fetch(`${url}/rest/v1/user_sync_snapshot`, {
        method: 'POST',
        headers,
        body: JSON.stringify(fullSnapshot)
      });
      console.log('[SyncService] Successfully pushed full snapshot to Supabase.');
    } catch (e) {
      console.warn('[SyncService] Push user_sync_snapshot failed:', e);
    }
  }

  /**
   * Supabaseから指定アカウントまたは全アカウント情報を検索・取得してローカルにマージ
   */
  static async fetchAccountFromCloud(targetUsername = null) {
    const config = this.getConfig();
    if (!config || !config.supabaseUrl || !config.supabaseAnonKey) return null;
    const url = this.cleanSupabaseUrl(config.supabaseUrl);
    const headers = {
      'apikey': config.supabaseAnonKey,
      'Authorization': `Bearer ${config.supabaseAnonKey}`,
      'Accept': 'application/json'
    };

    try {
      let endpoint = `${url}/rest/v1/user_accounts?select=*`;
      if (targetUsername) {
        endpoint += `&username=ilike.${encodeURIComponent(targetUsername.trim())}`;
      }
      let rows = [];
      try {
        const res = await fetch(endpoint, { headers });
        if (res.ok) {
          rows = await res.json();
        }
      } catch (_) {}

      // user_accounts が空またはテーブル未存在の場合、user_sync_snapshot からもアカウントを自動抽出
      if (!Array.isArray(rows) || rows.length === 0) {
        try {
          let snapEndpoint = `${url}/rest/v1/user_sync_snapshot?select=*`;
          if (targetUsername) {
            snapEndpoint += `&username=ilike.${encodeURIComponent(targetUsername.trim())}`;
          }
          const snapRes = await fetch(snapEndpoint, { headers });
          if (snapRes.ok) {
            const snaps = await snapRes.json();
            if (Array.isArray(snaps) && snaps.length > 0) {
              const fromSnap = snaps.filter(s => s.payload && s.payload.account).map(s => s.payload.account);
              if (fromSnap.length > 0) {
                AuthService.mergeServerUsers(fromSnap);
                return fromSnap;
              }
            }
          }
        } catch (_) {}
        return null;
      }

      const matched = rows.map(r => ({
        id: r.id,
        username: r.username,
        displayName: r.display_name || r.username,
        salt: r.salt,
        passwordHash: r.password_hash,
        recoverySalt: r.recovery_salt,
        recoveryCodeHash: r.recovery_code_hash,
        recoveryUsed: r.recovery_used,
        createdAt: r.created_at,
        lastLoginAt: r.last_login_at
      }));

      // ローカルユーザーにマージ
      AuthService.mergeServerUsers(matched);
      return matched;
    } catch (e) {
      console.warn('[SyncService] fetchAccountFromCloud failed:', e);
      return null;
    }
  }
}


